func flagCode(code string) string {
	c := strings.ToLower(code)
	if c == "" {
		return "ke"
	}
	return c
}

func calcBarPercent(count int, list []SpeciesTally) int {
	if len(list) == 0 {
		return 100
	}
	max := list[0].Count
	if max <= 0 {
		return 100
	}
	pct := (count * 100) / max
	if pct < 15 {
		pct = 15
	}
	return pct
}

